def charge_at(ph, seq):
    pK = dict(Cterm=3.55, Nterm=7.5, C=9.0, D=3.9, E=4.1, H=6.5, K=10.0, R=12.0, Y=10.1)
    q = 0
    q -= 1/(1+10**(pK['Cterm']-ph))
    q += 1/(1+10**(ph-pK['Nterm']))
    for a in seq:
        if a=='D': q -= 1/(1+10**(pK['D']-ph))
        if a=='E': q -= 1/(1+10**(pK['E']-ph))
        if a=='C': q -= 1/(1+10**(pK['C']-ph))
        if a=='Y': q -= 1/(1+10**(pK['Y']-ph))
        if a=='H': q += 1/(1+10**(ph-pK['H']))
        if a=='K': q += 1/(1+10**(ph-pK['K']))
        if a=='R': q += 1/(1+10**(ph-pK['R']))
    return q
